import Foundation

// Define a struct to hold user preferences and product information
struct UserPreferences {
    var favoriteColors: [String]
    var preferredProductType: String
}

// Define a function to generate a meaningful statement based on user preferences and product reviews
func generateStatement(preferences: UserPreferences, reviews: [String]) -> String {
    // Determine the user's favorite color and preferred product type
    let favoriteColor = preferences.favoriteColors.first ?? "not specified"
    let preferredProductType = preferences.preferredProductType

    // Generate a statement based on the user's preferences and product reviews
    let statement = "Based on your preference for \(favoriteColor) and \(preferredProductType), you might enjoy our \(reviews.first ?? "not available") product."

    return statement
}

// Example usage
let preferences = UserPreferences(favoriteColors: ["blue", "green"], preferredProductType: "electronics")
let reviews = ["The product is amazing.", "I love the design."]

let statement = generateStatement(preferences: preferences, reviews: reviews)
print(statement) // Output: Based on your preference for blue and electronics, you might enjoy our The product is amazing. product.
```

