  navigator.mediaDevices.getUserMedia({ video: true })
    .then(stream => {
      // Use the stream to access the camera
      console.log('Camera opened successfully');
    })
    .catch(error => {
      console.error('Error opening camera:', error);
    });
}

function closeCamera() {
  if (navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia().getTracks().forEach(track => track.stop());
  }
  console.log('Camera closed successfully');
}

function openMicrophone() {
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then(stream => {
      // Use the stream to access the microphone
      console.log('Microphone opened successfully');
    })
    .catch(error => {
      console.error('Error opening microphone:', error);
    });
}

function closeMicrophone() {
  if (navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia().getTracks().forEach(track => track.stop());
  }
  console.log('Microphone closed successfully');
}
```
