To find the kth largest element in the given list, we can use the quickselect algorithm. It has a time complexity of O(n), which is efficient for large lists. Here's a Python implementation of quickselect:

```python
def quickselect(lst, k):
    def partition(left, right):
        pivot = lst[right]
        i = left - 1
        for j in range(left, right):
            if lst[j] <= pivot:
                i += 1
                lst[i], lst[j] = lst[j], lst[i]
        lst[i + 1], lst[right] = lst[right], lst[i + 1]
        return i + 1

    def quick_select(left, right, k):
        if left == right:
            return lst[left]
        pivot_index = partition(left, right)
        if pivot_index == k - 1:
            return lst[pivot_index]
        elif pivot_index > k - 1:
            return quick_select(left, pivot_index - 1, k)
        else:
            return quick_select(pivot_index + 1, right, k)

    return quick_select(0, len(lst) - 1, k)

